  ,
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Reference class: probability that any party/coalition wins a 2/3 majority under Hungary's current electoral rules; historical occurrences anchor this baseline around 0.44."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around TISZA",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Greater opposition unity reduces fragmentation and makes it less likely for any single bloc to reach 133 seats, depressing the probability of a 2/3 majority."
      },
      {
        "factor": "Real-PR seat projection near two-thirds for Fidesz–KDNP",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Some seat-models place Fidesz–KDNP near the threshold under certain turnout and translation assumptions, signaling a non-zero upside."
      },
      {
        "factor": "Prediction markets favoring the opposition",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Markets tilted toward the opposition in early 2026, reducing the odds of a ruling-party 2/3 outcome."
      },
      {
        "factor": "Pre-election polls indicating no credible path to 2/3",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Polls project seat shares well below 133, signaling a low probability of a constitutional supermajority."
      },
      {
        "factor": "Historical base-rate precedent for 2/3 majorities",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Past occurrences show the event is possible under favorable turnout and dynamics, providing a non-zero ceiling."
      }
    ],
    "synthesis_rationale": "The posterior of 0.07 arises from dampening the anchor with predominantly downward signals from polls, fragmentation risk, and markets, while modestly lifting from favorable but uncertain signals like Real-PR projections and historical precedent. The range accounts for calibration uncertainty and potential correlation among factors, consistent with a cautious Bayesian update."
  }
}

